class BinarySearchTree:

 def __init__(self):
  self.root = None

 def add_node(self, value):
  if not self.root:
   self.root = Node(value)
  else: 
   self._add_node(self.root, value)

 def _add_node(self, node, value):
  if value <= node.value:
   if node.left:
    self._add_node(node.left, value)
   else:
    node.left = Node(value)
  else:
   if node.right:
    self._add_node(node.right, value)
   else:
    node.right = Node(value)

 def search(self, value):
  return self._search(self.root, value)

 def _search(self, node, value):
  if node is None:
   return False
  if node.value == value:
   return True
  else:
   if value <= node.value:
    return self._search(node.left, value)
   else: 
    return self._search(node.right, value)

 def get_size(self):
  return self._get_size(self.root)

 def _get_size(self, node):
  if not node:
   return 0
  return self._get_size(node.left) + 1 + self._get_size(node.right)

class Node:
 def __init__(self, val):
 self.val = val
 self.left = None
 self.right = None

class BinarySearchTree:
 def __init__(self):
 self.root = None

 def insert(self, val):
 newNode = Node(val)
 if self.root == None:
 self.root = newNode
 else:
 curr = self.root
 while curr:
 if val < curr.val:
 if curr.left == None:
 curr.left = newNode
 break
 else:
 curr = curr.left
 else:
 if curr.right == None:
 curr.right = newNode
 break
 else:
 curr = curr.right

 def delete(self, val):
 curr = self.root
 parent = None
 isLeftChild = True

 while curr.val != val:
 parent = curr
 if val < curr.val:
 curr = curr.left
 isLeftChild = True
 else:
 curr = curr.right
 isLeftChild = False

 if curr == None:
 return

 # if node has no children
 if curr.left == None and curr.right == None:
 if isLeftChild:
 parent.left = None
 else:
 parent.right = None

 # if node has one child
 elif curr.left == None:
 if isLeftChild:
 parent.left = curr.right
